// CF-05 · "Authorize Request" — role-based access control. The identity comes ONLY from the
// verified JWT; nothing in the request body can change who the user is.
const p = $input.first().json.payload || {};
const req = $('POST /cf/portal').first().json;
const b = req.body || {};
const ROLE_ACTIONS = {
  candidate: ['jobs', 'apply', 'my_applications', 'withdraw', 'chat'],
  employee:  ['jobs', 'chat'],
};                                    // HR staff use /cf/hr and /cf/hr/copilot instead
const action = String(b.action || '').toLowerCase().trim();
const role = p.role;
const denied = [];
if (p.iss !== 'companyflow' || p.aud !== 'companyflow-portal' || !p.sub) denied.push('invalid_token_claims');
else if (!ROLE_ACTIONS[role]) denied.push(`role "${role}" cannot use the portal API`);
else if (!ROLE_ACTIONS[role].includes(action)) denied.push(`action "${action}" is not allowed for role "${role}"`);
const invalid = [];
const message = String(b.message || '').slice(0, 2000);
if (!denied.length && action === 'chat' && !message.trim()) invalid.push('message is required');
const chatId = String(b.chat_id || 'main').toLowerCase().replace(/[^a-z0-9-]/g, '').slice(0, 32) || 'main';
return [{ json: {
  allowed: denied.length === 0 && invalid.length === 0,
  http_status: denied.length ? 403 : invalid.length ? 400 : 200,
  reasons: [...denied, ...invalid],
  action,
  identity: { user_id: p.sub, role, email: p.email, name: p.name },
  session_key: `${role}:${p.sub}:${chatId}`,   // memory is always scoped to the verified user
  message,
  body: b,
  ip: String((req.headers || {})['x-forwarded-for'] || '').split(',')[0].trim(),
} }];

// CF-05 · "Validate Application" — rejects incomplete / malformed submissions with clear codes
const a = $('Authorize Request').first().json;
const b = a.body || {};
const errors = [];
let status = 400;
const jobId = String(b.job_id || '').toUpperCase().trim();
if (!/^[A-Z0-9-]{2,20}$/.test(jobId)) errors.push('JOB_ID_REQUIRED');
if (b.consent !== true) errors.push('CONSENT_REQUIRED — you must agree to the processing of your data (Egypt PDPL 151/2020)');
const hasFile = typeof b.file_base64 === 'string' && b.file_base64.length > 0;
const text = String(b.resume_text || '');
const fileName = String(b.file_name || 'resume').slice(0, 120);
const ext = (fileName.split('.').pop() || '').toLowerCase();
let mime = String(b.mime_type || '').toLowerCase();
if (!mime) mime = ext === 'pdf' ? 'application/pdf' : ext === 'txt' ? 'text/plain' : '';
if (!hasFile && !text.trim()) errors.push('EMPTY_RESUME — upload a PDF/TXT file or paste your résumé');
if (hasFile) {
  const bytes = Math.floor(b.file_base64.replace(/^data:[^,]+,/, '').length * 3 / 4);
  if (bytes > 5 * 1024 * 1024) { errors.push('FILE_TOO_LARGE — maximum 5 MB'); status = 413; }
  if (!['application/pdf', 'text/plain'].includes(mime)) { errors.push('UNSUPPORTED_FORMAT — upload a PDF or .txt file, or paste the text (Word files: export as PDF)'); status = 415; }
}
if (text.length > 60000) errors.push('RESUME_TOO_LONG — maximum 60,000 characters');
return [{ json: {
  ok: errors.length === 0, errors, http_status: errors.length ? status : 200,
  job_id: jobId, has_file: hasFile, mime_type: mime, file_name: fileName,
  file_base64: hasFile ? b.file_base64.replace(/^data:[^,]+,/, '') : '',
  resume_text: text,
} }];

// CF-05 · "Merge Résumé Text" — one shape whatever the source (pasted text, PDF, TXT)
const j = $input.first().json;
const v = $('Validate Application').first().json;
let text = '';
let format = 'paste';
if (v.has_file) {
  format = v.mime_type === 'application/pdf' ? 'pdf' : 'text';
  text = String(j.text ?? j.resume_text_extracted ?? '');
} else {
  text = v.resume_text;
}
text = text.replace(/\u0000/g, '').trim();
let error = null;
if (format === 'pdf' && text.replace(/\s/g, '').length < 50) error = 'SCANNED_PDF_NO_TEXT — your PDF has no selectable text (it is probably a scan). Upload a text-based PDF or paste the text.';
else if (!text) error = 'EMPTY_RESUME — no text could be read from the file.';
return [{ json: { ok: !error, error, resume_text: text, resume_format: format, pages: j.numpages || null } }];

// CF-05 · "Prepare Reply" — normalises whichever agent answered
const j = $input.first().json;
const a = $('Authorize Request').first().json;
const reply = String(j.output || j.text || 'Sorry, I could not produce an answer. Please try again.');
return [{ json: { reply, agent: a.identity.role === 'candidate' ? 'careers_assistant' : 'policy_assistant', chars_in: a.message.length, chars_out: reply.length } }];
